fn frontmatter_title_works_with_bare() {
    setup();

    let graph = Graph::import(
        &from_indoc(indoc! {"
            [old](2)
            _
            title: Bare Title
            status: ready

            # Header
            "}),
        bare_options(),
        Some("title".to_string()),
    );

    let normalized = to_indoc(&graph.export());

    assert_str_eq!(
        indoc! {"
            [Bare Title](2)
            _
            title: Bare Title
            status: ready

            # Header
            "},
        normalized
    );
}

